1	/* ============================================================
2	   tierlist.js — 英雄梯度排行榜核心引擎
3	   支持 LOLM（分路/Z-score） 和 曙光英雄（无分路/加权和）
4	   ============================================================ */
5	
6	"use strict";
7	
8	// ---- 全局状态 ----
9	let gameConfig = null;      // 当前游戏的 config.json
10	let gameData = null;        // 计算后的结构化数据
11	let currentMethod = "zscore"; // LOLM: "zscore"|"simple", SG: "weighted"
12	let currentView = "lane";   // "lane"|"global"
13	let currentLane = null;     // 当前分路名（仅 hasLanes）
14	let currentViewMode = "table"; // "table"|"grid" — 展示模式
15	
16	// ---- 工具函数 ----
17	function parsePct(s) {
18	  if (typeof s === "number") return s / 100;
19	  return parseFloat(String(s).replace("%", "")) / 100;
20	}
21	
22	function mean(arr) {
23	  return arr.reduce((a, b) => a + b, 0) / arr.length;
24	}
25	
26	function stdDev(arr) {
27	  const m = mean(arr);
28	  const v = arr.reduce((s, v) => s + (v - m) ** 2, 0) / arr.length;
29	  return Math.sqrt(v) || 1;
30	}
31	
32	function zScores(arr) {
33	  const m = mean(arr);
34	  const s = stdDev(arr);
35	  if (s === 0) return arr.map(() => 0);
36	  return arr.map(v => (v - m) / s);
37	}
38	
39	function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }
40	
41	function getRankClass(rank) {
42	  if (rank === 1) return "rank-1";
43	  if (rank === 2) return "rank-2";
44	  if (rank === 3) return "rank-3";
45	  return "";
46	}
47	
48	function getWrClass(val) {
49	  if (val >= 0.52) return "wr-high";
50	  if (val >= 0.49) return "wr-mid";
51	  return "wr-low";
52	}
53	
54	function getCwClass(val) {
55	  // 战力分：高(>140) 中(80-140) 低(<80)
56	  if (val >= 140) return "cw-high";
57	  if (val >= 80) return "cw-mid";
58	  return "cw-low";
59	}
60	
61	// ---- 梯度系统 ----
62	function getTierColors() {
63	  return gameConfig.tiers.colors;
64	}
65	
66	function getTierThresholds() {
67	  return gameConfig.tiers.thresholds;
68	}
69	
70	function getTierBadge(tier) {
71	  const color = getTierColors()[tier] || "#8c8c8c";
72	  return `<span class="tier-badge" style="background:${color}">${tier}</span>`;
73	}
74	
75	function getScoreBar(score, tier) {
76	  const color = getTierColors()[tier] || "#8c8c8c";
77	  return `<div class="score-bar-wrap">
78	    <div class="score-bar"><div class="score-bar-fill" style="width:${score}%;background:${color}"></div></div>
79	    <span class="score-value">${score.toFixed(1)}</span></div>`;
80	}
81	
82	function assignTiers(heroes, scoreKey) {
83	  const sorted = [...heroes].sort((a, b) => b[scoreKey] - a[scoreKey]);
84	  const n = sorted.length;
85	  const thresholds = getTierThresholds();
86	  sorted.forEach((h, rank) => {
87	    const pct = 1 - rank / n;
88	    let tier = "T4";
89	    for (const t of thresholds) {
90	      if (pct >= t.pct) { tier = t.tier; break; }
91	    }
92	    h.tier = tier;
93	    h.rank = rank + 1;
94	  });
95	}
96	
97	// ============================================================
98	// LOLM 算法
99	// ============================================================
100	function computeLOLM(rawData) {
101	  const hasLanes = gameConfig.hasLanes;
102	  const lanes = {};
103	  const allHeroes = [];
104	
105	  for (const laneCfg of gameConfig.lanes) {
106	    const raw = rawData[laneCfg.name];
107	    if (!raw) continue;
108	    const heroes = raw.map(h => ({
109	      name: h.heroName,
110	      lane: laneCfg.name,
111	      headIcon: gameConfig.headIconPath ? (gameConfig.gameId + "/" + gameConfig.headIconPath.replace("{name}", h.heroName)) : null,
112	      wr: parsePct(h.winRate),
113	      pr: parsePct(h.pickRate),
114	      br: parsePct(h.banRate),
115	      bp: parsePct(h.pickRate) + parsePct(h.banRate)
116	    }));
117	    lanes[laneCfg.name] = heroes;
118	    allHeroes.push(...heroes);
119	  }
120	
121	  // Z-score 加权（分路内计算 Z-score）
122	  for (const [laneName, heroes] of Object.entries(lanes)) {
123	    const zWr = zScores(heroes.map(h => h.wr));
124	    const zPr = zScores(heroes.map(h => h.pr));
125	    const zBr = zScores(heroes.map(h => h.br));
126	    heroes.forEach((h, i) => {
127	      h.z_wr = zWr[i]; h.z_pr = zPr[i]; h.z_br = zBr[i];
128	      h.raw_zscore = 0.5 * zWr[i] + 1.0 * zPr[i] + 3.0 * zBr[i];
129	    });
130	  }
131	
132	  // 简易公式
133	  for (const [laneName, heroes] of Object.entries(lanes)) {
134	    heroes.forEach(h => {
135	      h.raw_simple = Math.pow(h.wr, 0.3) * (h.pr + 2.5 * h.br) * 100;
136	    });
137	  }
138	
139	  // 分路内 min-max 归一化
140	  function normalize(heroes, rawKey, normKey) {
141	    const vals = heroes.map(h => h[rawKey]);
142	    const lo = Math.min(...vals), hi = Math.max(...vals);
143	    const rng = hi - lo || 1;
144	    heroes.forEach(h => { h[normKey] = ((h[rawKey] - lo) / rng) * 100; });
145	  }
146	
147	  for (const [, heroes] of Object.entries(lanes)) {
148	    normalize(heroes, "raw_zscore", "score_zscore");
149	    normalize(heroes, "raw_simple", "score_simple");
150	  }
151	
152	  // 全局归一化
153	  normalize(allHeroes, "raw_zscore", "score_zscore_global");
154	  normalize(allHeroes, "raw_simple", "score_simple_global");
155	
156	  // 分配梯度
157	  for (const [, heroes] of Object.entries(lanes)) {
158	    assignTiersWithKey(heroes, "score_zscore", "tier_zscore");
159	    assignTiersWithKey(heroes, "score_simple", "tier_simple");
160	    assignTiersWithKey(heroes, "score_zscore_global", "tier_global");
161	  }
162	
163	  function assignTiersWithKey(heroes, scoreKey, tierKey) {
164	    const sorted = [...heroes].sort((a, b) => b[scoreKey] - a[scoreKey]);
165	    const n = sorted.length;
166	    const thresholds = getTierThresholds();
167	    sorted.forEach((h, i) => {
168	      const pct = 1 - i / n;
169	      let tier = "T4";
170	      for (const t of thresholds) {
171	        if (pct >= t.pct) { tier = t.tier; break; }
172	      }
173	      h[tierKey] = tier;
174	      // Store lane rank under a consistent key: _rank_zscore / _rank_simple
175	      if (tierKey === "tier_zscore") h._rank_zscore = i + 1;
176	      if (tierKey === "tier_simple") h._rank_simple = i + 1;
177	    });
178	  }
179	
180	  // 全局排名
181	  const globalZ = [...allHeroes].sort((a, b) => b.score_zscore_global - a.score_zscore_global);
182	  globalZ.forEach((h, i) => { h.global_rank_zscore = i + 1; });
183	  const globalSimple = [...allHeroes].sort((a, b) => b.score_simple_global - a.score_simple_global);
184	  globalSimple.forEach((h, i) => { h.global_rank_simple = i + 1; });
185	
186	  return { lanes, allHeroes, globalZ, globalSimple };
187	}
188	
189	// ============================================================
190	// 曙光英雄算法（从 Python validate_pure.py 移植）
191	// ============================================================
192	function computeSG(rawData) {
193	  const heroes = rawData.map(h => ({
194	    name: h.heroName,
195	    headIcon: gameConfig.headIconPath ? ("曙光英雄/" + gameConfig.headIconPath.replace("{name}", h.heroName)) : null,
196	    appearanceRank: parseInt(h.appearanceRank),
197	    combatPower: parseFloat(h.combatPower),
198	    winRate: parseFloat(String(h.winRate).replace("%", "")) / 100,
199	    lane: null
200	  }));
201	
202	  const N = heroes.length;
203	  const weights = gameConfig.algorithm.weights;
204	
205	  // 出场分：rank 越小越好，转换为 1 → 1.0, N → 0.0
206	  const appearanceScores = heroes.map(h => 1 - (h.appearanceRank - 1) / (N - 1));
207	
208	  // 战力分 min-max 归一化
209	  const combatVals = heroes.map(h => h.combatPower);
210	  const combatMin = Math.min(...combatVals), combatMax = Math.max(...combatVals);
211	  const combatRange = combatMax - combatMin || 1;
212	  const combatScores = combatVals.map(v => (v - combatMin) / combatRange);
213	
214	  // 胜率 min-max 归一化
215	  const wrVals = heroes.map(h => h.winRate);
216	  const wrMin = Math.min(...wrVals), wrMax = Math.max(...wrVals);
217	  const wrRange = wrMax - wrMin || 1;
218	  const wrScores = wrVals.map(v => (v - wrMin) / wrRange);
219	
220	  // 加权和
221	  heroes.forEach((h, i) => {
222	    h.raw_weighted = weights.appearance * appearanceScores[i]
223	                   + weights.combat * combatScores[i]
224	                   + weights.winrate * wrScores[i];
225	  });
226	
227	  // 最终 min-max 归一化 → 0~100
228	  const rawVals = heroes.map(h => h.raw_weighted);
229	  const rawMin = Math.min(...rawVals), rawMax = Math.max(...rawVals);
230	  const rawRange = rawMax - rawMin || 1;
231	  heroes.forEach(h => { h.score = ((h.raw_weighted - rawMin) / rawRange) * 100; });
232	
233	  // 分配梯度
234	  const sorted = [...heroes].sort((a, b) => b.score - a.score);
235	  const thresholds = getTierThresholds();
236	  sorted.forEach((h, i) => {
237	    const pct = 1 - i / N;
238	    let tier = "T4";
239	    for (const t of thresholds) {
240	      if (pct >= t.pct) { tier = t.tier; break; }
241	    }
242	    h.tier = tier;
243	    h.rank = i + 1;
244	  });
245	
246	  return { heroes, sorted };
247	}
248	
249	// ============================================================
250	// 数据加载 + 计算调度
251	// ============================================================
252	async function loadGameData() {
253	  const base = gameConfig.gameId === "lolm" ? "lolm" : "曙光英雄";
254	
255	  if (gameConfig.hasLanes) {
256	    // LOLM: 加载所有分路 JSON
257	    const results = await Promise.all(
258	      gameConfig.lanes.map(async lane => {
259	        const resp = await fetch(base + "/" + lane.dataFile);
260	        if (!resp.ok) throw new Error(`加载 ${lane.dataFile} 失败: ${resp.status}`);
261	        return [lane.name, await resp.json()];
262	      })
263	    );
264	    const rawData = Object.fromEntries(results);
265	    const data = computeLOLM(rawData);
266	
267	    // 转换为标准格式
268	    gameData = {
269	      hasLanes: true,
270	      lanes: {},
271	      allHeroes: data.allHeroes,
272	      globalZ: data.globalZ,
273	      globalSimple: data.globalSimple
274	    };
275	    for (const [name, heroes] of Object.entries(data.lanes)) {
276	      gameData.lanes[name] = heroes;
277	    }
278	  } else {
279	    // 曙光：加载单个 JSON
280	    const resp = await fetch(base + "/" + gameConfig.dataFile);
281	    if (!resp.ok) throw new Error(`加载数据失败: ${resp.status}`);
282	    const rawData = await resp.json();
283	    const data = computeSG(rawData);
284	    gameData = {
285	      hasLanes: false,
286	      heroes: data.heroes,
287	      sorted: data.sorted
288	    };
289	  }
290	}
291	
292	// ============================================================
293	// 获取当前有效的字段
294	// ============================================================
295	function getScoreField(hero) {
296	  if (gameConfig.hasLanes) {
297	    return currentMethod === "zscore" ? "score_zscore" : "score_simple";
298	  }
299	  return "score";
300	}
301	
302	function getTierField(hero) {
303	  if (gameConfig.hasLanes) {
304	    return currentMethod === "zscore" ? "tier_zscore" : "tier_simple";
305	  }
306	  return "tier";
307	}
308	
309	function getGlobalRank(hero) {
310	  if (gameConfig.hasLanes) {
311	    return hero[currentMethod === "zscore" ? "global_rank_zscore" : "global_rank_simple"];
312	  }
313	  return hero.rank;
314	}
315	
316	// ============================================================
317	// 渲染
318	// ============================================================
319	function formatCellValue(hero, col) {
320	  const val = hero[col.field];
321	  if (val == null) return "-";
322	
323	  switch (col.type) {
324	    case "rank":
325	      return `<span class="rank-num ${getRankClass(val)}">${val}</span>`;
326	    case "tier":
327	      return getTierBadge(val);
328	    case "score":
329	      return getScoreBar(val, hero.tier || hero[getTierField(hero)] || "T4");
330	    case "pct": {
331	      const pctVal = val * 100;
332	      let cls = "";
333	      if (col.colorClass === "wr") cls = getWrClass(val);
334	      if (col.colorClass === "cw") cls = getCwClass(val);
335	      return cls ? `<span class="${cls}">${pctVal.toFixed(2)}%</span>` : `${pctVal.toFixed(2)}%`;
336	    }
337	    case "int":
338	      return val.toString();
339	    default:
340	      return String(val);
341	  }
342	}
343	
344	function getSortValue(hero, col) {
345	  const val = hero[col.field];
346	  if (val == null) return 0;
347	  if (col.type === "tier") {
348	    const order = ["T0", "T0.5", "T1", "T2", "T3", "T4"];
349	    return order.indexOf(val);
350	  }
351	  if (typeof val === "number") return val;
352	  return String(val);
353	}
354	
355	function renderTable(heroes, columns, highlightLane) {
356	  // highlightLane: if set, highlight heroes from that lane
357	  let html = '<div class="table-wrapper"><table><thead><tr>';
358	  columns.forEach((col, idx) => {
359	    html += `<th onclick="sortTable(this, ${idx})" data-col-idx="${idx}">
360	      ${col.label} <span class="sort-icon">↕</span></th>`;
361	  });
362	  html += '</tr></thead><tbody>';
363	
364	  heroes.forEach(h => {
365	    let rowClass = "";
366	    if (highlightLane && h.lane === highlightLane) rowClass = ' class="current-highlight"';
367	    html += `<tr${rowClass}>`;
368	    columns.forEach(col => {
369	      // Resolve field value — some are computed
370	      let displayVal;
371	      if (col.field === "score") {
372	        displayVal = h[getScoreField(h)];
373	      } else if (col.field === "scoreGlobal") {
374	        displayVal = h[gameConfig.hasLanes ? (currentMethod === "zscore" ? "score_zscore_global" : "score_simple_global") : "score"];
375	      } else if (col.field === "tier") {
376	        displayVal = gameConfig.hasLanes ? h[getTierField(h)] : h.tier;
377	      } else if (col.field === "globalRank") {
378	        displayVal = getGlobalRank(h);
379	      } else {
380	        displayVal = h[col.field];
381	      }
382	
383	      // Format
384	      if (col.type === "rank") {
385	        html += `<td class="rank-num ${getRankClass(displayVal)}">${displayVal}</td>`;
386	      } else if (col.type === "tier") {
387	        html += `<td>${getTierBadge(displayVal)}</td>`;
388	      } else if (col.type === "score") {
389	        html += `<td>${getScoreBar(displayVal, h.tier || displayVal)}</td>`;
390	      } else if (col.type === "pct" && displayVal != null) {
391	        const pctVal = displayVal * 100;
392	        let cls = "";
393	        if (col.colorClass === "wr") cls = getWrClass(displayVal);
394	        if (col.colorClass === "cw") cls = getCwClass(displayVal);
395	        html += `<td class="${cls}">${pctVal.toFixed(2)}%</td>`;
396	      } else if (col.type === "int" && displayVal != null) {
397	        let cls = "";
398	        if (col.colorClass === "cw") cls = getCwClass(displayVal);
399	        html += `<td class="${cls}">${displayVal}</td>`;
400	      } else {
401	        let txt = displayVal != null ? displayVal : "-";
402	        // Render head icon + name for text columns when hero has an icon
403	        if (col.type === "text" && col.field === "name" && h.headIcon) {
404	          txt = `<div class="hero-cell"><img class="hero-icon" src="${h.headIcon}" alt="${h.name}" onerror="this.style.display='none'"> <span class="hero-name">${txt}</span></div>`;
405	        } else if (col.type === "text" && col.field === "name") {
406	          txt = `<span class="hero-name">${txt}</span>`;
407	        }
408	        html += `<td>${txt}</td>`;
409	      }
410	    });
411	    html += '</tr>';
412	  });
413	
414	  html += '</tbody></table></div>';
415	  return html;
416	}
417	
418	function renderGridView(heroes, highlightLane) {
419	  // 按梯度分组
420	  const tierOrder = ["T0", "T0.5", "T1", "T2", "T3", "T4"];
421	  const colors = getTierColors();
422	  const groups = {};
423	  tierOrder.forEach(t => { groups[t] = []; });
424	
425	  heroes.forEach(h => {
426	    const tier = gameConfig.hasLanes ? h[getTierField(h)] : h.tier;
427	    if (groups[tier]) groups[tier].push(h);
428	    else groups["T4"] = groups["T4"] || []; groups["T4"].push(h);
429	  });
430	
431	  // 组内按分数排序
432	  const scoreKey = getScoreField();
433	  tierOrder.forEach(t => {
434	    if (groups[t]) groups[t].sort((a, b) => b[scoreKey] - a[scoreKey]);
435	  });
436	
437	  let html = '<div class="tier-grid">';
438	  tierOrder.forEach(t => {
439	    const list = groups[t] || [];
440	    const color = colors[t] || "#8c8c8c";
441	    html += `<div class="tier-row${list.length === 0 ? " tier-row-empty" : ""}">`;
442	    html += `<div class="tier-label" style="background:${color}">${t}</div>`;
443	    html += '<div class="tier-icons">';
444	    if (list.length === 0) {
445	      html += '暂无英雄';
446	    } else {
447	      list.forEach(h => {
448	        const name = h.name;
449	        html += `<div class="tier-hero" title="${name}" onclick="doSearch('${name.replace(/'/g, "\\'")}')">`;
450	        if (h.headIcon) {
451	          html += `<img src="${h.headIcon}" alt="${name}" loading="lazy" onerror="this.style.display='none'">`;
452	        } else {
453	          html += `<div class="hero-icon-placeholder" style="width:44px;height:44px;border-radius:50%;background:#21262d;border:2px solid #30363d"></div>`;
454	        }
455	        html += `<span class="tier-hero-name">${name}</span>`;
456	        html += '</div>';
457	      });
458	    }
459	    html += '</div></div>';
460	  });
461	  html += '</div>';
462	  return html;
463	}
464	
465	function renderStatCards(heroes) {
466	  const cards = gameConfig.statCards;
467	  let html = '<div class="stats-row">';
468	  cards.forEach(card => {
469	    let displayVal;
470	    if (card.field === "winRateRange") {
471	      const wrVals = heroes.map(h => h.winRate * 100);
472	      displayVal = `${Math.min(...wrVals).toFixed(1)}% ~ ${Math.max(...wrVals).toFixed(1)}%`;
473	    } else if (card.field === "count") {
474	      displayVal = heroes.length;
475	    } else if (card.format === "pct") {
476	      const vals = heroes.map(h => h[card.field] * 100);
477	      displayVal = mean(vals).toFixed(1) + "%";
478	    } else if (card.format === "int") {
479	      const vals = heroes.map(h => h[card.field]);
480	      displayVal = Math.round(mean(vals));
481	    } else {
482	      displayVal = String(heroes.length);
483	    }
484	    html += `<div class="stat-card">
485	      <div class="stat-value">${displayVal}</div>
486	      <div class="stat-label">${card.label}</div></div>`;
487	  });
488	  html += '</div>';
489	  return html;
490	}
491	
492	function renderLaneView(laneName) {
493	  if (!gameData.hasLanes) {
494	    // 曙光：无分路，直接全量渲染
495	    const heroes = gameData.heroes;
496	    const sorted = [...heroes].sort((a, b) => a.rank - b.rank);
497	    let html = `<div class="section-header">
498	      <h2>${gameConfig.gameIcon} ${gameConfig.gameName} 梯度排行</h2>
499	      <span class="count-badge">${heroes.length} 个英雄</span></div>`;
500	    html += renderStatCards(heroes);
501	    html += renderTable(sorted, gameConfig.columns, null);
502	    return html;
503	  }
504	
505	  // LOLM：分路渲染
506	  const heroes = gameData.lanes[laneName];
507	  if (!heroes) return "<p>无数据</p>";
508	
509	  const scoreKey = getScoreField();
510	  const tierKey = getTierField();
511	  const rankKey = currentMethod === "zscore" ? "_rank_zscore" : "_rank_simple";
512	  const sorted = [...heroes].sort((a, b) => b[scoreKey] - a[scoreKey]);
513	  // Set display rank from precomputed lane rank
514	  sorted.forEach((h) => { h.laneRank = h[rankKey]; });
515	
516	  // Build lane-specific columns (with global rank column appended)
517	  const laneCols = gameConfig.columns.map(col => {
518	    if (col.field === "rank") return { ...col, field: "laneRank" };
519	    return col;
520	  });
521	  // Append global rank column
522	  laneCols.push({ label: "全局排名", field: "globalRank", type: "rank" });
523	
524	  let html = `<div class="section-header">
525	    <h2>${laneName}</h2>
526	    <span class="count-badge">${heroes.length} 个英雄</span></div>`;
527	  html += renderStatCards(heroes);
528	  html += renderTable(sorted, laneCols, null);
529	  return html;
530	}
531	
532	function renderGlobalView() {
533	  if (!gameData.hasLanes) {
534	    // 曙光无分路模式没有"全局"视图，显示一个汇总
535	    return renderLaneView();
536	  }
537	
538	  const all = currentMethod === "zscore" ? gameData.globalZ : gameData.globalSimple;
539	  // Re-rank
540	  all.forEach((h, i) => { h.globalRank = i + 1; });
541	
542	  let html = `<div class="section-header">
543	    <h2>🌍 全局排名（跨分路对比）</h2>
544	    <span class="count-badge">${all.length} 个英雄</span>
545	    <span class="hint">⚠️ 不同分路英雄职责不同，建议以分路内排名为主</span></div>`;
546	  html += renderTable(all, gameConfig.globalColumns, null);
547	  return html;
548	}
549	
550	function renderAll() {
551	  if (!gameData) return;
552	  const content = document.getElementById("content");
553	
554	  // 网格视图 — 单独处理
555	  if (currentViewMode === "grid") {
556	    let heroes;
557	    if (!gameData.hasLanes) {
558	      heroes = gameData.heroes;
559	    } else if (currentView === "global") {
560	      heroes = currentMethod === "zscore" ? gameData.globalZ : gameData.globalSimple;
561	    } else {
562	      heroes = gameData.lanes[currentLane] || [];
563	    }
564	
565	    let titleHtml;
566	    if (!gameData.hasLanes) {
567	      titleHtml = `<div class="section-header">
568	        <h2>${gameConfig.gameIcon} ${gameConfig.gameName} 梯度排行</h2>
569	        <span class="count-badge">${heroes.length} 个英雄</span></div>`;
570	    } else if (currentView === "global") {
571	      titleHtml = `<div class="section-header">
572	        <h2>🌍 全局排名（跨分路对比）</h2>
573	        <span class="count-badge">${heroes.length} 个英雄</span>
574	        <span class="hint">⚠️ 不同分路英雄职责不同，建议以分路内排名为主</span></div>`;
575	    } else {
576	      titleHtml = `<div class="section-header">
577	        <h2>${currentLane}</h2>
578	        <span class="count-badge">${heroes.length} 个英雄</span></div>`;
579	    }
580	    content.innerHTML = titleHtml + renderGridView(heroes, null);
581	    return;
582	  }
583	
584	  // 表格视图
