602	    renderAll();
603	    return;
604	  }
605	  const q = query.trim().toLowerCase();
606	  let results = [];
607	
608	  if (gameData.hasLanes) {
609	    for (const heroes of Object.values(gameData.lanes)) {
610	      for (const h of heroes) {
611	        if (h.name.toLowerCase().includes(q)) results.push(h);
612	      }
613	    }
614	  } else {
615	    results = gameData.heroes.filter(h => h.name.toLowerCase().includes(q));
616	  }
617	
618	  if (results.length === 0) {
619	    document.getElementById("content").innerHTML =
